//! Audio files generated by the tests themselves.
//!
//! Keystone depends on no encoder — symphonia decodes only — so the containers
//! that can be built here are the ones whose bitstream is writable by hand:
//! RIFF/WAVE, AIFF, and a structurally valid MPEG Layer III stream whose frames
//! carry no main data. That is enough to cover the container paths, the
//! downmix, the resample, the levels and the tag-offset rule. The compressed
//! codecs' *decoder* throughput is measured by the benchmark against real
//! files, which is the only honest way to get that number.

use std::f32::consts::TAU;
use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};

pub struct Pcm {
    pub channels: u16,
    pub sample_rate: u32,
    /// Interleaved, in [-1, 1].
    pub samples: Vec<f32>,
}

impl Pcm {
    pub fn frames(&self) -> usize {
        self.samples.len() / self.channels.max(1) as usize
    }
}

/// A sine at `hz`, the same in every channel.
pub fn tone(hz: f32, amplitude: f32, seconds: f32, sample_rate: u32, channels: u16) -> Pcm {
    let frames = (seconds * sample_rate as f32) as usize;
    let mut samples = Vec::with_capacity(frames * channels as usize);
    for i in 0..frames {
        let v = amplitude * (TAU * hz * i as f32 / sample_rate as f32).sin();
        for _ in 0..channels {
            samples.push(v);
        }
    }
    Pcm {
        channels,
        sample_rate,
        samples,
    }
}

/// Two channels holding opposite constants, so an arithmetic-mean downmix is
/// exactly silence and anything else is not.
pub fn opposed(level: f32, frames: usize, sample_rate: u32) -> Pcm {
    let mut samples = Vec::with_capacity(frames * 2);
    for _ in 0..frames {
        samples.push(level);
        samples.push(-level);
    }
    Pcm {
        channels: 2,
        sample_rate,
        samples,
    }
}

pub fn constant(level: f32, frames: usize, sample_rate: u32, channels: u16) -> Pcm {
    Pcm {
        channels,
        sample_rate,
        samples: vec![level; frames * channels as usize],
    }
}

pub fn wav(dir: &Path, name: &str, pcm: &Pcm, bits: u16, float: bool) -> PathBuf {
    let data: Vec<u8> = pcm
        .samples
        .iter()
        .flat_map(|s| sample_bytes(*s, bits, float))
        .collect();
    write(dir, name, &wav_bytes(pcm, bits, float, &data))
}

/// A WAV whose `data` chunk promises more bytes than the file contains, which
/// is what a part-copied or interrupted download looks like.
pub fn truncated_wav(dir: &Path, name: &str, pcm: &Pcm, keep_fraction: f32) -> PathBuf {
    let data: Vec<u8> = pcm
        .samples
        .iter()
        .flat_map(|s| sample_bytes(*s, 16, false))
        .collect();
    let full = wav_bytes(pcm, 16, false, &data);
    let header = full.len() - data.len();
    let keep = header + (data.len() as f32 * keep_fraction) as usize;
    write(dir, name, &full[..keep.min(full.len())])
}

fn wav_bytes(pcm: &Pcm, bits: u16, float: bool, data: &[u8]) -> Vec<u8> {
    let block_align = (bits / 8) * pcm.channels;
    let mut out = Vec::with_capacity(data.len() + 44);
    out.extend_from_slice(b"RIFF");
    out.extend_from_slice(&(36 + data.len() as u32).to_le_bytes());
    out.extend_from_slice(b"WAVEfmt ");
    out.extend_from_slice(&16u32.to_le_bytes());
    out.extend_from_slice(&if float { 3u16 } else { 1u16 }.to_le_bytes());
    out.extend_from_slice(&pcm.channels.to_le_bytes());
    out.extend_from_slice(&pcm.sample_rate.to_le_bytes());
    out.extend_from_slice(&(pcm.sample_rate * u32::from(block_align)).to_le_bytes());
    out.extend_from_slice(&block_align.to_le_bytes());
    out.extend_from_slice(&bits.to_le_bytes());
    out.extend_from_slice(b"data");
    out.extend_from_slice(&(data.len() as u32).to_le_bytes());
    out.extend_from_slice(data);
    out
}

fn sample_bytes(s: f32, bits: u16, float: bool) -> Vec<u8> {
    if float {
        return s.to_le_bytes().to_vec();
    }
    match bits {
        24 => {
            let v = (s * 8_388_607.0) as i32;
            v.to_le_bytes()[..3].to_vec()
        }
        32 => ((s * 2_147_483_647.0) as i32).to_le_bytes().to_vec(),
        _ => ((s * 32_767.0) as i16).to_le_bytes().to_vec(),
    }
}

/// AIFF is big-endian throughout, and its sample rate is an 80-bit IEEE 754
/// extended float — the one field that cannot be written by casting.
pub fn aiff(dir: &Path, name: &str, pcm: &Pcm) -> PathBuf {
    let data: Vec<u8> = pcm
        .samples
        .iter()
        .flat_map(|s| ((s * 32_767.0) as i16).to_be_bytes())
        .collect();
    let ssnd_len = 8 + data.len() as u32;
    let mut out = Vec::with_capacity(data.len() + 54);
    out.extend_from_slice(b"FORM");
    out.extend_from_slice(&(4 + 8 + 18 + 8 + ssnd_len).to_be_bytes());
    out.extend_from_slice(b"AIFFCOMM");
    out.extend_from_slice(&18u32.to_be_bytes());
    out.extend_from_slice(&pcm.channels.to_be_bytes());
    out.extend_from_slice(&(pcm.frames() as u32).to_be_bytes());
    out.extend_from_slice(&16u16.to_be_bytes());
    out.extend_from_slice(&extended_rate(pcm.sample_rate));
    out.extend_from_slice(b"SSND");
    out.extend_from_slice(&ssnd_len.to_be_bytes());
    out.extend_from_slice(&0u32.to_be_bytes()); // offset
    out.extend_from_slice(&0u32.to_be_bytes()); // block size
    out.extend_from_slice(&data);
    write(dir, name, &out)
}

fn extended_rate(rate: u32) -> [u8; 10] {
    let mut out = [0u8; 10];
    let exponent = 31 - rate.leading_zeros(); // floor(log2(rate))
    let shift = 63 - u64::from(exponent);
    let mantissa = u64::from(rate) << shift;
    out[..2].copy_from_slice(&((16_383 + exponent) as u16).to_be_bytes());
    out[2..].copy_from_slice(&mantissa.to_be_bytes());
    out
}

/// MPEG Layer III, 44.1 kHz stereo, one frame per entry in `bitrates_kbps`, no
/// main data. Structurally valid, so the demuxer and the probe see a real
/// variable-rate stream; the granules decode to silence.
pub fn mp3(dir: &Path, name: &str, bitrates_kbps: &[u32], id3_bytes: usize) -> PathBuf {
    let mut out = Vec::new();
    if id3_bytes > 0 {
        out.extend_from_slice(&id3v2(id3_bytes));
    }
    for kbps in bitrates_kbps {
        let index = bitrate_index(*kbps);
        let frame_len = 144 * (*kbps as usize) * 1000 / 44_100;
        out.extend_from_slice(&[0xFF, 0xFB, (index << 4) & 0xF0, 0x04]);
        out.extend(std::iter::repeat_n(0u8, frame_len.saturating_sub(4)));
    }
    write(dir, name, &out)
}

/// An ID3v2.3 block of exactly `total` bytes, which is what a re-tag rewrites
/// and resizes at the head of an MP3.
fn id3v2(total: usize) -> Vec<u8> {
    let body = total.max(10) - 10;
    let mut out = Vec::with_capacity(total);
    out.extend_from_slice(b"ID3");
    out.extend_from_slice(&[3, 0, 0]);
    // The size is a 28-bit synchsafe integer: seven bits per byte.
    for shift in [21, 14, 7, 0] {
        out.push(((body >> shift) & 0x7F) as u8);
    }
    out.extend(std::iter::repeat_n(0u8, body));
    out
}

fn bitrate_index(kbps: u32) -> u8 {
    const TABLE: [u32; 15] = [
        0, 32, 40, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320,
    ];
    TABLE.iter().position(|v| *v == kbps).unwrap_or(9) as u8
}

/// A 128-byte ID3v1 tag, appended. The content hash must not notice it.
pub fn append_id3v1(path: &Path) {
    let mut tag = Vec::with_capacity(128);
    tag.extend_from_slice(b"TAG");
    tag.extend(std::iter::repeat_n(0u8, 125));
    let mut file = fs::OpenOptions::new().append(true).open(path).expect("append");
    file.write_all(&tag).expect("append the tag");
}

/// Writes a long mono WAV in chunks, so the fixture for a DJ-length mix never
/// exists in memory all at once.
pub fn long_wav(dir: &Path, name: &str, seconds: u32, sample_rate: u32) -> PathBuf {
    let frames = seconds as usize * sample_rate as usize;
    let path = dir.join(name);
    let pcm = Pcm {
        channels: 1,
        sample_rate,
        samples: Vec::new(),
    };
    let mut file = fs::File::create(&path).expect("create the long fixture");
    file.write_all(&wav_bytes(&pcm, 16, false, &[])[..36])
        .expect("riff header");
    file.write_all(b"data").expect("data chunk");
    file.write_all(&((frames * 2) as u32).to_le_bytes())
        .expect("data length");

    let mut block = Vec::with_capacity(sample_rate as usize * 2);
    for i in 0..sample_rate as usize {
        let v = 0.25 * (TAU * 220.0 * i as f32 / sample_rate as f32).sin();
        block.extend_from_slice(&((v * 32_767.0) as i16).to_le_bytes());
    }
    for _ in 0..seconds {
        file.write_all(&block).expect("audio block");
    }
    // The RIFF size field was written against an empty data chunk; patch it.
    let riff_len = 36 + frames as u32 * 2;
    use std::io::{Seek, SeekFrom};
    file.seek(SeekFrom::Start(4)).expect("seek");
    file.write_all(&riff_len.to_le_bytes()).expect("riff size");
    path
}

fn write(dir: &Path, name: &str, bytes: &[u8]) -> PathBuf {
    let path = dir.join(name);
    fs::write(&path, bytes).expect("the fixture could not be written");
    path
}
